import {validateRecord} from './model.js';
import {externalize,visitMedia,mediaKeys,registerMedia,isMediaKey,mediaInfo,adoptStoredMedia} from './media-store.js';
import {clearDraftInTransaction} from './drafts.js';
export function openJournalDatabase(factory=globalThis.indexedDB){return new Promise((resolve,reject)=>{const r=factory.open('nth-footprints',2);r.onupgradeneeded=()=>{for(const name of ['journal','media'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name);};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Close other FootPrints tabs, then reload to upgrade storage.'));});}
const transaction=(db,stores,mode,work)=>new Promise((resolve,reject)=>{const tx=db.transaction(stores,mode);let value;try{work(tx,v=>value=v);}catch(e){tx.abort();reject(e);return;}tx.oncomplete=()=>resolve(value);tx.onabort=()=>reject(tx.error??Error('Local storage could not finish.'));tx.onerror=()=>{};});
export function createJournalStorage(db){
 const staged=new Set();
 const get=(store,key)=>transaction(db,[store],'readonly',(tx,set)=>{tx.objectStore(store).get(key).onsuccess=e=>set(e.target.result);});
 async function hydrate(rows,fromDisk=false){const keys=mediaKeys(rows),map=new Map();for(const key of keys){const cached=mediaInfo(key);if(cached&&!fromDisk){map.set(key,cached.url);continue;}const stored=await get('media',key);if(!stored?.blob)throw Error('An original attachment is missing. Keep this app installed and restore a complete backup.');map.set(key,cached?adoptStoredMedia(key,stored.blob):await registerMedia(stored.blob,{key,crc:stored.crc}));}return visitMedia(rows,p=>isMediaKey(p)?map.get(p):p);}
 async function collect(){await transaction(db,['journal','media'],'readwrite',tx=>{const journal=tx.objectStore('journal');journal.get('state').onsuccess=e=>{const state=e.target.result;if(!state||state.storageVersion!==2)return;const keep=new Set([...mediaKeys(state.records),...staged]);const media=tx.objectStore('media'),cursor=media.openKeyCursor();cursor.onsuccess=e=>{const c=e.target.result;if(c){if(!keep.has(c.key))media.delete(c.key);c.continue();}};};});}
 return {
  async read(){const state=await get('journal','state');if(!state)return state;if(state.storageVersion===2)return {...state,records:await hydrate(state.records)};const prepared=await externalize(state.records.map(validateRecord));try{await transaction(db,['journal','media'],'readwrite',tx=>{for(const row of prepared.entries){const media=tx.objectStore('media');media.getKey(row.key).onsuccess=e=>{if(e.target.result===undefined)media.put({blob:row.blob,crc:row.crc},row.key);};}tx.objectStore('journal').put({...state,storageVersion:2,records:prepared.records},'state');});}catch(error){return {...state,storageWarning:'Original media could not yet move to the new storage. Your existing journal is intact. Create a backup, then free device space and reopen.',records:await hydrate(prepared.records)};}return {...state,records:await hydrate(prepared.records,true)};},
  async write(rows,settings,clearDraftId,journeys){const added=[];const prepared=await externalize(rows.map(validateRecord));await transaction(db,['journal','media'],'readwrite',tx=>{for(const row of prepared.entries){const media=tx.objectStore('media');media.getKey(row.key).onsuccess=e=>{if(e.target.result===undefined){media.put({blob:row.blob,crc:row.crc},row.key);added.push(row.key);}};}tx.objectStore('journal').put({storageVersion:2,records:prepared.records,settings,journeys},'state');if(clearDraftId)clearDraftInTransaction(tx.objectStore('journal'),clearDraftId);});for(const key of added){const saved=await get('media',key);adoptStoredMedia(key,saved.blob);}await collect().catch(()=>{});return (await hydrate(prepared.records)).map(validateRecord);},
  async stage(blob,key){staged.add(key);let added=false;const url=await registerMedia(blob,{key});const row=mediaInfo(url);await transaction(db,['media'],'readwrite',tx=>{const media=tx.objectStore('media');media.getKey(row.key).onsuccess=e=>{if(e.target.result===undefined){media.put({blob:row.blob,crc:row.crc},row.key);added=true;}};});if(added){const saved=await get('media',key);return adoptStoredMedia(key,saved.blob);}return url;},
  collect,
  async releaseStage(){staged.clear();await collect();},
  hydrate
 };
}
